    commits: [
      "chore: update dependencies",
      "feat: implement streaming API",
      "fix: handle null values correctly",
      "test: add integration tests",
      "feat(auth): add OAuth2 support",
      "docs: document OAuth2 setup",
      "refactor: simplify parser logic",
